@module editorRender  src=editorRender.lua  loc=258  mode=chunk  self=er
@deps swingEditor, temperEditor, cmgr, chrome, gui, modalHost

# Invariants & contracts
  @contract  render-only; owns pane-selection UI state; reaches the swing/temper panes, never cm/ds  @ 9
  @contract  body editor — focusState always page-suppresses (root globals stay live, page bindings off)  @ 10

# Shapes
  @shape  libraryTreeSpec = { x, y, h, label, active={{col,name}}, project={name}, library={name}, synthetic={[name]=true}, undeletable={[name]=true}, modified={[name]=true}, sel={tier,name}, dirty?:bool, onSelect(tier,name), onNew(), onImport?(), onPublish(name), onRevert(name), onImportFactory(name), onTidy?(), onReloadFactory?(), onReset?(), onDelete(tier,name) }  @ 31
  @shape  ToolbarSegment = { id, render = fn(), visible? = fn() -> bool }  @ 182
  @shape  focusState = { suppressKbd:bool, pageSuppressed:bool, acceptCmds:bool }  @ 247

# Imports
